pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MaliciousListener {
    C immutable target;
    bool public reentered;
    address public observedBaseToken;
    constructor(C _target) { target = _target; }
    /* This fallback is triggered when the Initialize event is emitted.
       In the mutant, baseToken is still zero at this point. */
    receive() external payable {
        if (!reentered) {
            reentered = true;
            observedBaseToken = target.baseToken();
        }
    }
    /* The factory needs a way to trigger the reentrant callback.
       deployAndInitialize is called by the test after setting up the listener. */
    function deployAndInitialize(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) external returns (address _pool) {
        // deploy a minimal proxy that calls initialize and emits the event;
        // the proxy's deterministic address will be the listener's address.
        _pool = address(220);
        target.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );
    }
}

contract InvMutTest is Test {
    C c;
    MaliciousListener listener;
    function setUp() public {
        // Deploy C using exactly the required constructor arguments
        c = new C(address(this), address(this), address(this));
        // Deploy a listener that captures reentrant baseToken before final storage
        listener = new MaliciousListener(c);
    }
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Restrict _feeRate to <= 5000 to avoid expected revert for both versions
        vm.assume(_feeRate <= 5000);
        // For the reentrancy to succeed, the listener must be capable of receiving ether,
        // so we ensure _baseToken != listener and _nft != listener to avoid tx reverts.
        vm.assume(_baseToken != address(listener) && _nft != address(listener));
        // The listener triggers reentry only once, but we also prevent the listener
        // from being the caller to avoid state corruption (caller is the listener itself).
        // The factory-like call from listener will invoke initialize directly on c.
        // This requires that c.initialize can be called; no owner check exists.
        vm.prank(address(listener));
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            // On success, the invariant must hold
            assertTrue(listener.reentered() ? listener.observedBaseToken() == _baseToken : true);
        } catch {
            // If initialize reverts, the invariant vacuously holds
            assertTrue(true);
        }
    }
}

