pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address firstNft, address secondNft) public {
        vm.assume(firstNft != address(0) && secondNft != address(0));
        vm.assume(firstNft != secondNft);

        // first successful initialization
        c.initialize(address(0), firstNft, 1e18, 1e18, 0, 100, bytes32(0), false, false);
        address afterFirst = c.nft();

        assertEq(afterFirst, firstNft, "setup failed");

        // second initialization that must revert because contract is already initialized
        bool reverted = false;
        try c.initialize(address(0), secondNft, 1e18, 1e18, 0, 100, bytes32(0), false, false) {
        } catch {
            reverted = true;
        }
        require(reverted, "expected revert did not happen");

        // After a reverted initialization, nft MUST still be the original value (firstNft).
        // The bug moves `nft = _nft` before the revert guard, so it changes to secondNft.
        assertEq(c.nft(), firstNft);
    }
}

