pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address nft1, address nft2, uint64 changeFee, uint16 feeRate, bool useStolenNftOracle, bool payRoyalties) public {
        // 1. keep params in admissible domain
        vm.assume(nft1 != address(0) && nft2 != address(0));
        vm.assume(nft1 != nft2);
        if (feeRate > 5000) feeRate = 5000;

        // 2. first successful initialization
        c.initialize(address(0), nft1, 0, 0, changeFee, feeRate, bytes32(0), useStolenNftOracle, payRoyalties);
        assertTrue(c.nft() == nft1);

        // second call must revert (already initialized) and not change nft
        bool reverted;
        try c.initialize(address(0), nft2, 0, 0, changeFee, feeRate, bytes32(0), useStolenNftOracle, payRoyalties) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 3. assertion: nft remains nft1 regardless of the revert
        assertTrue(reverted && c.nft() == nft1);
    }
}

